/**
 * ExecutionPanel — 执行台面板。
 *
 * 垂直三等分三个区域：
 * 1. 任务列表 — 最近 48 小时内的所有任务（顶部）— 增强版
 * 2. 调用栈 — 聚合当前会话中 assistant 消息的 tool_calls（中部）
 * 3. 预览 — 展示工作区中选中的文件内容预览（底部）
 */
import { useCallback, useEffect, useRef, useState } from 'react'
import {
  ClipboardList, FileText, Loader2, Wrench,
  CheckCircle2, Circle, XCircle, Clock,
  ChevronRight, ChevronDown, AlertTriangle, RotateCcw, Plus,
  Maximize2, Minimize2, X,
} from 'lucide-react'
import { api, type FileInfo, type Message, type ToolCallInfo, type TaskInfo } from '@/lib/api'
import { ToolCallLine } from '@/components/chat/ToolCallLine'

interface ExecutionPanelProps {
  messages: Message[]
  selectedFile: FileInfo | null
  selectedFileRoot?: number
  selectedProjectId?: string | null
}

const TASK_REFRESH_MS = 15_000

export function ExecutionPanel({ messages, selectedFile, selectedFileRoot = 0, selectedProjectId }: ExecutionPanelProps) {
  const [tasks, setTasks] = useState<TaskInfo[]>([])
  const [tasksLoading, setTasksLoading] = useState(false)
  const [fileContent, setFileContent] = useState<string | null>(null)
  const [fileLoading, setFileLoading] = useState(false)
  const [taskFilter, setTaskFilter] = useState<string>('all')
  const [showCreateInput, setShowCreateInput] = useState(false)
  const [newTaskMessage, setNewTaskMessage] = useState('')
  const tasksTimerRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // 聚合所有 assistant 消息的 tool_calls
  const allToolCalls: { toolCall: ToolCallInfo; messageIndex: number }[] = []
  messages.forEach((msg, idx) => {
    if (msg.role === 'assistant' && msg.tool_calls) {
      msg.tool_calls.forEach((tc) => {
        allToolCalls.push({ toolCall: tc, messageIndex: idx })
      })
    }
  })

  // 加载任务列表
  const loadTasks = useCallback(async () => {
    try {
      const status = taskFilter === 'all' ? undefined : taskFilter
      const data = await api.getRecentTasks(48, undefined, status, selectedProjectId || undefined)
      setTasks(data)
    } catch {
      // ignore
    } finally {
      setTasksLoading(false)
    }
  }, [taskFilter, selectedProjectId])

  useEffect(() => {
    setTasksLoading(true)
    loadTasks()
    tasksTimerRef.current = setInterval(loadTasks, TASK_REFRESH_MS)
    return () => {
      if (tasksTimerRef.current) clearInterval(tasksTimerRef.current)
    }
  }, [loadTasks])

  // 创建任务
  const handleCreateTask = async () => {
    if (!newTaskMessage.trim()) return
    try {
      await api.createTask({ message: newTaskMessage.trim(), kind: 'chat' })
      setNewTaskMessage('')
      setShowCreateInput(false)
      loadTasks()
    } catch { /* ignore */ }
  }

  // 重试任务
  const handleRetry = async (taskId: string) => {
    try {
      await api.retryTask(taskId)
      loadTasks()
    } catch { /* ignore */ }
  }

  // 加载选中文件的内容
  useEffect(() => {
    if (!selectedFile) {
      setFileContent(null)
      return
    }
    setFileLoading(true)
    api.readFileContent(selectedFileRoot, selectedFile.path)
      .then((resp) => setFileContent(resp.content))
      .catch(() => setFileContent(null))
      .finally(() => setFileLoading(false))
  }, [selectedFile, selectedFileRoot])

  return (
    <div className="flex h-full flex-col bg-background">
      {/* 顶部：任务列表 */}
      <div className="flex-1 flex flex-col min-h-0 border-b">
        <div className="flex items-center gap-1.5 px-3 py-2 border-b shrink-0">
          <ClipboardList className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-xs font-medium">任务</span>
          {tasks.length > 0 && (
            <span className="rounded-full bg-primary/10 text-primary px-1.5 py-0.5 text-[10px]">
              {tasks.length}
            </span>
          )}
          <div className="ml-auto flex items-center gap-1">
            <select
              value={taskFilter}
              onChange={(e) => setTaskFilter(e.target.value)}
              className="h-5 text-[10px] rounded border bg-background px-1 text-muted-foreground"
            >
              <option value="all">全部</option>
              <option value="pending">待执行</option>
              <option value="running">执行中</option>
              <option value="completed">已完成</option>
              <option value="failed">失败</option>
            </select>
            <button
              onClick={() => setShowCreateInput(!showCreateInput)}
              className="h-5 w-5 flex items-center justify-center rounded hover:bg-accent text-muted-foreground hover:text-foreground transition-colors"
              title="新建任务"
            >
              <Plus className="h-3 w-3" />
            </button>
          </div>
        </div>
        {/* 内联创建输入框 */}
        {showCreateInput && (
          <div className="px-3 py-2 border-b bg-accent/20">
            <div className="flex gap-1.5">
              <input
                value={newTaskMessage}
                onChange={(e) => setNewTaskMessage(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleCreateTask()}
                placeholder="输入任务描述..."
                className="flex-1 h-6 text-xs rounded border bg-background px-2 placeholder:text-muted-foreground/50"
                autoFocus
              />
              <button
                onClick={handleCreateTask}
                className="h-6 px-2 text-[10px] rounded bg-primary text-primary-foreground hover:bg-primary/90"
              >
                创建
              </button>
            </div>
          </div>
        )}
        <div className="flex-1 overflow-y-auto">
          <TaskListView tasks={tasks} loading={tasksLoading} onRetry={handleRetry} />
        </div>
      </div>

      {/* 中部：调用栈 */}
      <div className="flex-1 flex flex-col min-h-0 border-b">
        <div className="flex items-center gap-1.5 px-3 py-2 border-b shrink-0">
          <Wrench className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-xs font-medium">调用栈</span>
          {allToolCalls.length > 0 && (
            <span className="rounded-full bg-primary/10 text-primary px-1.5 py-0.5 text-[10px]">
              {allToolCalls.length}
            </span>
          )}
        </div>
        <div className="flex-1 overflow-y-auto">
          <ToolCallStack toolCalls={allToolCalls} />
        </div>
      </div>

      {/* 底部：预览 */}
      <div className="flex-1 flex flex-col min-h-0">
        <div className="flex items-center gap-1.5 px-3 py-2 border-b shrink-0">
          <FileText className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-xs font-medium">预览</span>
          {selectedFile && (
            <span className="rounded-full bg-primary/10 text-primary px-1.5 py-0.5 text-[10px]">
              1
            </span>
          )}
        </div>
        <div className="flex-1 overflow-y-auto">
          <PreviewView
            file={selectedFile}
            content={fileContent}
            loading={fileLoading}
          />
        </div>
      </div>
    </div>
  )
}

/** 任务列表视图（增强版）。 */
function TaskListView({ tasks, loading, onRetry }: {
  tasks: TaskInfo[]
  loading: boolean
  onRetry: (id: string) => void
}) {
  if (loading && tasks.length === 0) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
      </div>
    )
  }

  if (tasks.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 px-4">
        <ClipboardList className="h-7 w-7 text-muted-foreground/30" />
        <p className="mt-2 text-xs text-muted-foreground text-center">暂无任务</p>
        <p className="mt-1 text-[10px] text-muted-foreground/60 text-center">
          最近 48 小时内的任务会显示在这里
        </p>
      </div>
    )
  }

  return (
    <div className="divide-y divide-border/40">
      {tasks.map((task) => (
        <TaskCard key={task.id} task={task} onRetry={onRetry} />
      ))}
    </div>
  )
}

/** 单个任务卡片（增强版 — 进度条、优先级、子任务折叠、错误重试）。 */
function TaskCard({ task, onRetry }: { task: TaskInfo; onRetry: (id: string) => void }) {
  const [expanded, setExpanded] = useState(false)
  const [subtasks, setSubtasks] = useState<TaskInfo[]>([])
  const hasSubtasks = task.subtasks && task.subtasks.length > 0

  const toggleExpand = async () => {
    if (!expanded && !hasSubtasks) {
      // 懒加载子任务
      try {
        const detail = await api.getTaskDetail(task.id)
        if (detail.subtasks) setSubtasks(detail.subtasks)
      } catch { /* ignore */ }
    }
    setExpanded(!expanded)
  }

  const priority = task.priority || 5
  const priorityLabel = priority <= 2 ? 'P1' : priority <= 4 ? 'P2' : priority <= 6 ? 'P3' : 'P4'
  const priorityColor = priority <= 2
    ? 'bg-red-100 text-red-700'
    : priority <= 4
      ? 'bg-amber-100 text-amber-700'
      : priority <= 6
        ? 'bg-slate-100 text-slate-600'
        : 'bg-blue-50 text-blue-600'

  const progress = task.progress || 0
  const progressColor = task.status === 'completed'
    ? 'bg-emerald-500'
    : task.status === 'failed'
      ? 'bg-red-500'
      : 'bg-blue-500'

  const showProgress = task.status === 'running' || task.status === 'completed' || progress > 0

  return (
    <div className="px-3 py-2 hover:bg-accent/30 transition-colors">
      {/* 主行 */}
      <div className="flex items-center gap-1.5">
        <TaskStatusIcon status={task.status} />
        <span className={`rounded-full px-1 py-0.5 text-[9px] font-medium ${priorityColor}`}>
          {priorityLabel}
        </span>
        <span className="text-[11px] truncate flex-1 text-foreground/80">
          {task.message || '(无描述)'}
        </span>
        <span className="text-[10px] text-muted-foreground/70 shrink-0">
          {formatDuration(task.created_at, task.completed_at)}
        </span>
      </div>

      {/* 进度条 */}
      {showProgress && (
        <div className="flex items-center gap-2 mt-1">
          <div className="flex-1 h-1.5 rounded-full bg-muted overflow-hidden">
            <div
              className={`h-full rounded-full transition-all duration-300 ${progressColor}`}
              style={{ width: `${Math.min(100, progress)}%` }}
            />
          </div>
          <span className="text-[9px] text-muted-foreground/70 w-7 text-right">
            {progress}%
          </span>
        </div>
      )}

      {/* 错误摘要 + 重试 */}
      {task.status === 'failed' && task.error_message && (
        <div className="flex items-center gap-1.5 mt-1">
          <AlertTriangle className="h-2.5 w-2.5 text-red-500 shrink-0" />
          <span className="text-[10px] text-red-600 truncate flex-1">
            {task.error_type ? `[${task.error_type}] ` : ''}{task.error_message}
          </span>
          <button
            onClick={() => onRetry(task.id)}
            className="flex items-center gap-0.5 text-[10px] text-blue-500 underline cursor-pointer hover:text-blue-600 shrink-0"
          >
            <RotateCcw className="h-2.5 w-2.5" />
            重试
          </button>
        </div>
      )}

      {/* 底部元信息 */}
      <div className="flex items-center gap-3 mt-1 text-[10px] text-muted-foreground/70">
        <span className="flex items-center gap-0.5">
          <Clock className="h-2.5 w-2.5" />
          {formatTime(task.created_at)}
        </span>
        {task.token_used > 0 && (
          <span className="ml-auto">{task.token_used.toLocaleString()} tokens</span>
        )}
        {task.kind && task.kind !== 'chat' && (
          <span className={`rounded px-1 py-0.5 text-[9px] ${
            task.kind === 'project' ? 'bg-purple-100 text-purple-700' :
            task.kind === 'scheduled' ? 'bg-amber-100 text-amber-700' :
            'bg-slate-100 text-slate-600'
          }`}>
            {task.kind}
          </span>
        )}
      </div>
    </div>
  )
}

/** 任务状态图标。 */
function TaskStatusIcon({ status }: { status: string }) {
  switch (status) {
    case 'completed':
    case 'done':
      return <CheckCircle2 className="h-3 w-3 text-emerald-500 shrink-0" />
    case 'running':
    case 'pending':
      return <Circle className="h-3 w-3 text-blue-500 shrink-0 animate-pulse" />
    case 'error':
    case 'failed':
      return <XCircle className="h-3 w-3 text-red-500 shrink-0" />
    case 'cancelled':
      return <XCircle className="h-3 w-3 text-muted-foreground/40 shrink-0" />
    default:
      return <Circle className="h-3 w-3 text-muted-foreground/40 shrink-0" />
  }
}

/** 格式化时间。 */
function formatTime(iso: string): string {
  try {
    const d = new Date(iso)
    const now = new Date()
    const diffMs = now.getTime() - d.getTime()
    const diffMin = Math.floor(diffMs / 60000)
    if (diffMin < 1) return '刚刚'
    if (diffMin < 60) return `${diffMin}分钟前`
    const diffHr = Math.floor(diffMin / 60)
    if (diffHr < 24) return `${diffHr}小时前`
    return d.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
  } catch {
    return iso
  }
}

/** 格式化耗时。 */
function formatDuration(startIso: string, endIso: string | null): string {
  try {
    const start = new Date(startIso)
    const end = endIso ? new Date(endIso) : new Date()
    const diffMs = end.getTime() - start.getTime()
    const diffMin = Math.floor(diffMs / 60000)
    if (diffMin < 1) return '<1m'
    if (diffMin < 60) return `${diffMin}m`
    const diffHr = Math.floor(diffMin / 60)
    const remainMin = diffMin % 60
    return `${diffHr}h${remainMin}m`
  } catch {
    return ''
  }
}

/** 调用栈视图 — 聚合展示所有工具调用。 */
function ToolCallStack({
  toolCalls,
}: {
  toolCalls: { toolCall: ToolCallInfo; messageIndex: number }[]
}) {
  if (toolCalls.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-10 px-4">
        <Wrench className="h-7 w-7 text-muted-foreground/30" />
        <p className="mt-2 text-xs text-muted-foreground text-center">暂无工具调用</p>
        <p className="mt-1 text-[10px] text-muted-foreground/60 text-center">
          Agent 执行工具时就在此显示调用栈
        </p>
      </div>
    )
  }

  const reversed = [...toolCalls].reverse()

  return (
    <div className="space-y-1.5 p-3">
      {reversed.map(({ toolCall }, i) => (
        <ToolCallLine key={`${toolCall.id}-${i}`} toolCall={toolCall} />
      ))}
    </div>
  )
}

/** 预览视图 — 文件内容预览，支持全屏放大。 */
function PreviewView({
  file,
  content,
  loading,
}: {
  file: FileInfo | null
  content: string | null
  loading: boolean
}) {
  const [isFullscreen, setIsFullscreen] = useState(false)

  // Esc 键退出全屏
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isFullscreen) {
        setIsFullscreen(false)
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isFullscreen])

  if (!file) {
    return (
      <div className="flex flex-col items-center justify-center py-10 px-4">
        <FileText className="h-7 w-7 text-muted-foreground/30" />
        <p className="mt-2 text-xs text-muted-foreground text-center">暂无预览</p>
        <p className="mt-1 text-[10px] text-muted-foreground/60 text-center">
          在左侧工作区选择文件以预览内容
        </p>
      </div>
    )
  }

  return (
    <>
      <div className="flex flex-col h-full">
        {/* 文件信息栏 */}
        <div className="flex items-center gap-2 border-b px-3 py-2 shrink-0">
          <FileText className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
          <span className="text-xs font-medium truncate">{file.name}</span>
          <span className="text-[10px] text-muted-foreground shrink-0">
            {file.size < 1024
              ? `${file.size}B`
              : file.size < 1024 * 1024
                ? `${(file.size / 1024).toFixed(1)}K`
                : `${(file.size / 1024 / 1024).toFixed(1)}M`}
          </span>
          <button
            onClick={() => setIsFullscreen(true)}
            className="ml-auto rounded p-0.5 text-muted-foreground hover:text-foreground transition-colors shrink-0"
            title="放大预览"
          >
            <Maximize2 className="h-3.5 w-3.5" />
          </button>
        </div>

        {/* 文件内容 */}
        <div className="flex-1 overflow-auto">
          {loading ? (
            <div className="flex items-center justify-center py-6">
              <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
            </div>
          ) : content === null ? (
            <div className="px-3 py-6 text-center">
              <p className="text-xs text-muted-foreground">无法加载文件内容</p>
            </div>
          ) : (
            <pre className="p-3 text-xs leading-relaxed text-muted-foreground whitespace-pre-wrap break-all font-mono">
              {content}
            </pre>
          )}
        </div>
      </div>

      {/* 全屏预览覆盖层 */}
      {isFullscreen && (
        <div className="fixed inset-0 z-50 flex flex-col bg-background">
          {/* 全屏顶部栏 */}
          <div className="flex items-center gap-2 border-b px-4 py-3 shrink-0">
            <FileText className="h-4 w-4 text-muted-foreground shrink-0" />
            <span className="text-sm font-medium truncate">{file.name}</span>
            <span className="text-xs text-muted-foreground shrink-0">
              {file.size < 1024
                ? `${file.size}B`
                : file.size < 1024 * 1024
                  ? `${(file.size / 1024).toFixed(1)}K`
                  : `${(file.size / 1024 / 1024).toFixed(1)}M`}
            </span>
            <div className="ml-auto flex items-center gap-1">
              <button
                onClick={() => setIsFullscreen(false)}
                className="rounded-md p-1 text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
                title="缩小"
              >
                <Minimize2 className="h-4 w-4" />
              </button>
              <button
                onClick={() => setIsFullscreen(false)}
                className="rounded-md p-1 text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
                title="关闭"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          </div>
          {/* 全屏内容 */}
          <div className="flex-1 overflow-auto">
            {loading ? (
              <div className="flex items-center justify-center py-10">
                <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
              </div>
            ) : content === null ? (
              <div className="px-4 py-10 text-center">
                <p className="text-sm text-muted-foreground">无法加载文件内容</p>
              </div>
            ) : (
              <pre className="p-6 text-sm leading-relaxed text-muted-foreground whitespace-pre-wrap break-all font-mono">
                {content}
              </pre>
            )}
          </div>
        </div>
      )}
    </>
  )
}
